+/* Add a FT_RELATIVE_TIME to a proto_tree as service response time. */
+proto_item *
+proto_tree_add_srt(proto_tree *tree, int hfindex, const packet_info *pinfo,
+		const nstime_t *reftime_ptr)
+{
+	return proto_tree_add_srt_ret_val(tree, hfindex, pinfo, reftime_ptr, NULL);
+}
+
+proto_item *
+proto_tree_add_srt_ret_val(proto_tree *tree, int hfindex, const packet_info *pinfo,
+		const nstime_t *reftime_ptr, nstime_t *srt_ptr)
+{
+	proto_item	  *pi;
+	header_field_info *hfinfo;
+	int dummy = 0;
+	nstime_t ns, *ns_ptr;
+
+	/* Ensure we calculate a value, even if not showing anything. */
+	if (srt_ptr != NULL)
+		proto_srt_delta_since_ref_time(srt_ptr, pinfo, reftime_ptr);
+
+	CHECK_FOR_NULL_TREE(tree);
+
+	TRY_TO_FAKE_THIS_ITEM(tree, hfindex, hfinfo);
+
+	DISSECTOR_ASSERT_FIELD_TYPE(hfinfo, FT_RELATIVE_TIME);
+
+	if (srt_ptr) {
+		ns_ptr = srt_ptr;
+	} else {
+		ns_ptr = &ns;
+		proto_srt_delta_since_ref_time(ns_ptr, pinfo, reftime_ptr);
+	}
+
+	pi = proto_tree_add_pi(tree, hfinfo, NULL, 0, &dummy);
+	proto_tree_set_time(PNODE_FINFO(pi), ns_ptr);
+	proto_item_set_generated(pi);
+
+	return pi;
+}
