+/* Calculate a reference time for SRT taking time shift into account. */
+void proto_srt_set_ref_time(nstime_t *reftime_ptr, const packet_info *pinfo)
+{
+	*reftime_ptr = pinfo->abs_ts;
+	nstime_delta(reftime_ptr, reftime_ptr, &pinfo->fd->shift_offset);
+}
+
+/* Calculate delta to a reference time set using abs_ts on first parse of trace. */
+void
+proto_srt_delta_since_ref_time(nstime_t *delta, const packet_info *pinfo,
+		const nstime_t *reftime_ptr)
+{
+	nstime_delta(delta, &pinfo->abs_ts, reftime_ptr);
+	nstime_delta(delta, delta, &pinfo->fd->shift_offset);
+}
